#!/usr/bin/env python3
"""Ajouts C85 sourcés du 02.11.2026; uniquement sources de la mission réservée."""
from pathlib import Path
import json,re,hashlib
from lxml import etree
ROOT=Path(__file__).resolve().parents[5]
OUT=Path(__file__).resolve().parent
ONKO='https://www.onkopedia.com/de/onkopedia/guidelines/diffuses-grosszelliges-b-zell-lymphom/@@guideline/html/index.html'
NAPPI='https://pmc.ncbi.nlm.nih.gov/articles/PMC12101282/'
RADIO='https://pmc.ncbi.nlm.nih.gov/articles/PMC3579993/'
EHA='https://pmc.ncbi.nlm.nih.gov/articles/PMC12456099/'
HIST='https://pmc.ncbi.nlm.nih.gov/articles/PMC6909622/'
NORMAL='https://openstax.org/books/anatomy-and-physiology-2e/pages/20-5-circulatory-pathways'
def cite(url,label):return f'<a href="{url}" target="_blank" rel="noopener">{label}</a>'
def source(*pairs):return '<p class="src">Passages de référence : '+ ' ; '.join(cite(u,l) for u,l in pairs)+'.</p>'
sections=[
('normal','Le normal : un passage central pour le sang, l’air et les aliments',f'''<p>Avant d’interpréter un gonflement du visage, il faut situer le trajet du sang. La veine cave supérieure ramène vers l’oreillette droite le sang de la tête, du cou, du thorax et des membres supérieurs. Elle réunit ainsi des territoires éloignés en un même trajet veineux central. Un signe observé au visage peut donc révéler une difficulté située dans le thorax, et non une affection locale du visage.</p><p>Le médiastin se situe entre les cavités pleurales, depuis l’entrée du thorax jusqu’au diaphragme. La localisation antérieure d’une masse est un premier renseignement anatomique ; elle n’est pas son diagnostic histologique. En effet, une affection thymique, un lymphome, une lésion thyroïdienne ou une tumeur germinale peuvent occuper ce compartiment. Le raisonnement doit relier le territoire atteint à l’imagerie, puis à la nature du tissu prélevé.</p>{source((NORMAL,'OpenStax, retour veineux et veine cave supérieure'),(RADIO,'Juanpere et al., Introduction et masses médiastinales'))}'''),
('signs','Les symptômes : distinguer compression locale et retentissement général',f'''<p>Dans le lymphome médiastinal, la toux, la dyspnée et la dysphagie appartiennent à la présentation compressive. L’interrogatoire précise leur apparition, leur progression et leur association. Il recherche aussi un gonflement du visage ou des bras ainsi qu’une distension des veines du cou et du thorax. Ces constatations correspondent au <button class="w" data-k="c85-vcs">syndrome cave supérieur</button> décrit dans les sources ; elles orientent vers une atteinte du retour veineux central.</p><p>En revanche, les <button class="w" data-k="c85-symptomes-b">symptômes B</button> décrivent le retentissement général. La définition utilisée par Onkopedia comprend une fièvre inexpliquée supérieure à 38 °C, des sueurs nocturnes nécessitant de changer le linge, ou une perte de poids inexpliquée supérieure à 10 % en six mois. Ces seuils définissent les symptômes, pas à eux seuls le lymphome. Le poids antérieur, la durée et les autres explications possibles doivent donc être précisés.</p><p>La présence d’une masse médiastinale ne se résume pas aux ganglions palpables. La revue de Nappi rapporte que l’atteinte ganglionnaire à distance est rare dans cette entité. Ainsi, l’examen des aires superficielles et l’exploration du thorax répondent à deux questions différentes ; un examen périphérique peu contributif ne remplace pas l’imagerie de la masse.</p>{source((ONKO,'Onkopedia, §3, §4.2 et §5.2.1'),(NAPPI,'Nappi et al., Introduction, présentation clinique'))}'''),
('mechanisms','Le mécanisme : expliquer la distribution des signes',f'''<p>La chaîne explicative du syndrome cave supérieur associe une masse médiastinale, une atteinte de la veine cave et des manifestations dans les territoires qu’elle draine. Les veines thoraciques et cervicales deviennent visibles ou distendues ; le visage et les bras présentent un œdème. Ce rapprochement est une interprétation anatomoclinique du trajet normal et des signes rapportés, pas une mesure de pression veineuse chez le patient.</p><p>La dyspnée n’identifie pas un mécanisme unique. La masse peut s’accompagner d’une compression des voies aériennes, d’un épanchement pleural ou d’un épanchement péricardique. Le scanner recherche ces rapports et ces complications. Par conséquent, attribuer toute gêne respiratoire à une simple compression bronchique ferait perdre des informations importantes sur l’extension locale.</p><p>Enfin, la taille de la masse et sa nature sont deux dimensions distinctes. Les signes compressifs traduisent ses rapports avec les organes voisins ; l’immunohistochimie et l’analyse du tissu déterminent le type de lymphome. Un symptôme intense n’est donc pas une preuve d’un sous-type, et un marqueur isolé ne décrit pas la tolérance respiratoire du patient.</p>{source((NORMAL,'OpenStax, drainage cave supérieur'),(NAPPI,'Nappi et al., présentation et imagerie'),(EHA,'EHA 2025, diagnostic et anatomopathologie'))}'''),
('examination','L’examen : observer, préciser puis confronter à l’imagerie',f'''<p>L’examen recherche les manifestations décrites dans la présentation clinique : œdème du visage ou des bras, distension veineuse cervicale ou thoracique, ainsi que les signes d’une atteinte respiratoire. La description doit préciser le siège et l’évolution ; le terme « syndrome cave » ne remplace pas le détail des constatations. Les symptômes rapportés par le patient et les signes effectivement observés restent distingués dans la synthèse.</p><p>Pour le bilan clinique du lymphome, Onkopedia demande aussi l’examen des amygdales, des aires ganglionnaires, du foie, de la rate, des épanchements et des masses visibles ou palpables. Cette recherche systématique complète l’évaluation thoracique. Elle ne donne toutefois ni la taille précise de la masse médiastinale ni l’identité de ses cellules.</p><p>Le scanner avec contraste décrit la localisation, l’extension et les rapports de la masse. La <button class="w" data-k="c85-biopsie">biopsie</button> répond ensuite à la question tissulaire. Une observation clinique, une coupe d’imagerie et un prélèvement ne sont donc pas trois versions du même examen : chacun apporte une information nécessaire au raisonnement.</p>{source((ONKO,'Onkopedia, §4.1 et §4.2'),(NAPPI,'Nappi et al., présentation et bilan diagnostique'))}'''),
('interpretation','L’interprétation : localiser ne signifie pas identifier',f'''<p>Une masse du médiastin antérieur, une progression rapide et des signes compressifs sont compatibles avec un lymphome médiastinal primitif à grandes cellules B. Cependant, l’ensemble clinique ne suffit pas à le distinguer de toutes les autres lésions médiastinales. La confirmation repose sur l’intégration de la présentation, de la morphologie et du phénotype immunologique.</p><p>Les recommandations européennes de 2025 demandent une expertise hématopathologique disposant des techniques immunohistochimiques et moléculaires adaptées. Le prélèvement doit permettre de reconnaître une population B mature et de distinguer les sous-types pertinents. Cette exigence explique pourquoi la mention « lymphome B » reste parfois une étape du diagnostic, et non sa conclusion définitive.</p><p>Après traitement, une masse résiduelle et un foyer métabolique persistant ne sont pas interchangeables. Pour les lymphomes à grandes cellules B, les recommandations européennes indiquent qu’un résultat métabolique positif en fin de traitement peut nécessiter une biopsie ou un contrôle. Dans le lymphome médiastinal, elles encouragent en particulier la biopsie des lésions classées Deauville 4. Un compte rendu isolé ne doit donc pas être transformé automatiquement en preuve de maladie réfractaire.</p>{source((EHA,'EHA 2025, diagnostic, réponse et lymphome médiastinal'),(NAPPI,'Nappi et al., diagnostic et limites de la TEP'))}'''),
('differentials','Les différentiels : utiliser la localisation puis le tissu',f'''<p>Dans le médiastin antérieur, les principaux groupes à discuter comprennent les lésions thymiques, thyroïdiennes, germinales et lymphomateuses. L’imagerie décrit la composition de la masse et ses rapports ; l’histoire clinique et l’âge aident à hiérarchiser les possibilités. Ces indices orientent le prélèvement et les examens, mais ne remplacent pas une preuve tissulaire lorsque celle-ci est nécessaire.</p><p>Au sein des lymphomes, la distinction concerne notamment le lymphome médiastinal primitif, le lymphome de Hodgkin classique et les lymphomes médiastinaux de zone grise. Leurs caractères peuvent se recouvrir. L’étude anatomopathologique de Kim et collaborateurs montre l’intérêt de la fibrose réticulaire ou compartimentante et d’un ensemble de marquages ; elle ne permet pas de poser le diagnostic à partir d’une photographie isolée ou d’un seul marqueur.</p><p>La démarche reste donc progressive : localiser la lésion, caractériser ses constituants, recueillir un échantillon représentatif, puis intégrer les résultats morphologiques et immunologiques. La qualification finale conditionne la suite du traitement ; elle mérite une relecture spécialisée lorsqu’une discordance persiste.</p>{source((RADIO,'Juanpere et al., masses du médiastin antérieur'),(HIST,'Kim et al. 2019, résultats histologiques et figure2'),(EHA,'EHA 2025, diagnostic spécialisé'))}'''),
('urgency','La priorité : évaluer le retentissement compressif',f'''<p>Le lymphome médiastinal peut progresser rapidement et provoquer une compression des voies aériennes ou une obstruction du retour veineux supérieur. La priorité clinique est donc d’identifier ces atteintes et leur retentissement, plutôt que de commencer par le seul calcul d’un score pronostique. Les plaintes respiratoires, l’œdème cervicofacial et les signes d’épanchement doivent être mis en relation avec l’imagerie.</p><p>Les sources citées décrivent ces complications et les examens qui les caractérisent. Elles ne fournissent pas, pour tous les patients, un délai chiffré universel ni un schéma unique de traitement d’urgence. Une décision invasive, anesthésique ou thérapeutique doit être contextualisée par l’équipe spécialisée ; aucune posologie de secours n’est déduite de cette seule analyse sémiologique.</p><div class="alert"><b>À reconnaître en premier.</b> Une masse thoracique accompagnée de manifestations respiratoires ou d’un syndrome cave supérieur exige d’abord une appréciation de la compression et de sa tolérance. Le classement du lymphome ne remplace pas cette évaluation clinique.</div>{source((ONKO,'Onkopedia, §5.2.1'),(NAPPI,'Nappi et al., présentation et imagerie'))}'''),
('limits','Les limites : garder le périmètre de chaque source',f'''<p>La recommandation Onkopedia associe notamment les sociétés suisses d’hématologie et d’oncologie médicale. Les recommandations européennes de 2025 apportent une actualisation distincte : dans le lymphome médiastinal, elles recommandent des schémas tels que R-CHOP14 ou DA-EPOCH-R et demandent d’éviter R-CHOP21. Cette dernière proposition vise l’entité médiastinale ; elle ne doit pas être étendue sans distinction à tout lymphome diffus à grandes cellules B.</p><p>La revue radiologique de 2013 illustre la localisation et les images, sans servir de recommandation thérapeutique actuelle. L’étude histologique coréenne de 2019 sert ici à reconnaître les structures de sa planche, sans transposer ses fréquences à la population suisse. Quant au chapitre OpenStax, il étaye le trajet veineux normal et non une conduite thérapeutique.</p><p>Les indications et les doses des produits utilisés en Suisse restent contrôlées dans leurs informations professionnelles exactes. Ainsi, la fiche Polivy consultée le 2 novembre 2026, mise à jour en novembre 2025, indique l’association avec bendamustine et rituximab en rechute ou réfractarité chez les adultes non admissibles à une greffe. Une recommandation européenne ne suffit pas à modifier cette indication suisse.</p>{source((EHA,'EHA 2025, sous-section lymphome médiastinal'),('https://amiko.oddb.org/fr/fi?gtin=7680671650020','FI suisse Polivy, indications et date de mise à jour'),(RADIO,'Juanpere et al. 2013'),(HIST,'Kim et al. 2019'))}'''),
('sources','Des sources reliées aux questions de la leçon',f'''<p>Le trajet veineux normal provient du chapitre OpenStax sur les voies circulatoires. Les limites anatomiques du médiastin et la lecture des coupes proviennent de Juanpere et collaborateurs. Les signes compressifs, les épanchements et le bilan du lymphome médiastinal sont décrits dans Onkopedia et dans la revue de Nappi de 2025.</p><p>Les recommandations européennes de 2025 étayent l’expertise diagnostique, la place de l’imagerie métabolique et les précautions d’interprétation après traitement. La planche de Kim et collaborateurs est une illustration histologique authentique. Les passages utiles ont été consultés le 2 novembre 2026 ; les données anciennes du reste du cours conservent leurs références propres et leurs limites.</p>{source((ONKO,'Onkopedia, §3, §4.1–4.2 et §5.2.1'),(NAPPI,'Nappi et al. 2025, Introduction'),(RADIO,'Juanpere et al. 2013, Introduction et figure25'),(HIST,'Kim et al. 2019, figure2'),(EHA,'EHA 2025'),(NORMAL,'OpenStax, §20.5'))}''')]
semio='<div class="sci" id="c85-s-semio" role="tabpanel" aria-labelledby="c85-tab-semio"><section class="ilot" id="c85-semio-intro"><h2>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h2><p>La sémiologie relie ce que le patient ressent, ce que l’examen observe et ce que les examens démontrent. Dans cette leçon, elle explique surtout comment une masse médiastinale produit des signes à distance et pourquoi ces signes ne remplacent pas le diagnostic tissulaire.</p></section>'
for marker,title,body in sections:semio+=f'<section class="ilot" id="c85-semio-{marker}" data-semiology="{marker}"><h3>{title}</h3>{body}</section>'
semio+='</div>'
physio=f'''<div class="sci" id="c85-s-physio" hidden><section class="ilot" id="c85-physio-cours"><h2>Physiologie : comprendre un obstacle au retour veineux</h2><p>La circulation veineuse supérieure rassemble des territoires éloignés avant leur retour au cœur. Ce trajet explique la distribution des manifestations d’une obstruction médiastinale. Il permet de passer d’un signe observé au visage à une question anatomique précise.</p><p>En situation normale, les veines de la tête et du cou rejoignent les voies brachiocéphaliques ; le sang des membres supérieurs rejoint également ce réseau. La veine cave supérieure ramène ensuite le sang vers l’oreillette droite. Le diaphragme fournit un repère pédagogique pour distinguer les territoires principalement drainés par la veine cave supérieure et ceux drainés par la veine cave inférieure ; il ne faut pas en faire une frontière absolue pour tous les circuits veineux.</p><p>Lorsqu’une masse médiastinale compromet ce trajet supérieur, les manifestations décrites dans le lymphome médiastinal associent la distension des veines du thorax et du cou à un œdème du visage et des bras. Le lien entre ces signes et la localisation de la masse devient alors intelligible. Cette explication est anatomoclinique ; ni une pression veineuse ni une sensibilité diagnostique ne sont attribuées à un signe sans mesure ou étude correspondante.</p><p>Le retentissement respiratoire doit être étudié séparément. Les sources décrivent à la fois la compression des voies aériennes et les épanchements pleuraux ou péricardiques. La coexistence possible de plusieurs mécanismes explique pourquoi l’imagerie doit montrer les rapports de la masse, et non seulement son diamètre.</p><div class="key"><b>Lien avec la clinique.</b> La distribution cervicofaciale et brachiale des signes oriente l’étude du retour veineux supérieur.</div><div class="key"><b>Lien avec les examens.</b> Le scanner caractérise la masse et recherche ses rapports avec les structures vasculaires et respiratoires ainsi que les épanchements.</div><div class="key"><b>Lien avec le traitement.</b> L’évaluation du retentissement compressif complète le diagnostic tissulaire ; elle ne permet pas de choisir seule le schéma d’immunochimiothérapie.</div>{source((NORMAL,'OpenStax, §20.5, retour veineux'),(NAPPI,'Nappi et al. 2025, présentation et imagerie'),(EHA,'EHA 2025, diagnostic'))}<div class="key"><b>À retenir.</b> La topographie des signes s’explique par les trajets normaux. La nature du lymphome et la gravité de sa compression répondent à deux questions complémentaires.</div></section></div>'''
p=ROOT/'chapters/C85/C85_c.html';text=p.read_text()
if 'id="c85-s-semio"' not in text:
 text=text.replace('<div class="sci-bar ui" role="tablist">','<div class="sci-bar ui" role="tablist"><button id="c85-tab-semio" role="tab" aria-selected="true" aria-controls="c85-s-semio" data-s="c85-s-semio">Sémiologie fondamentale et analytique</button>',1)
 text=text.replace('aria-selected="true" aria-controls="c85-s-anat"','aria-selected="false" aria-controls="c85-s-anat"',1)
 text=text.replace('<div class="chap-body sci-body">','<div class="chap-body sci-body">'+semio+physio,1)
 text=text.replace('<div class="sci" id="c85-s-anat">','<div class="sci" id="c85-s-anat" hidden>',1)
 text=text.replace('data-s="c85-s-histo">Histologie</button>','data-s="c85-s-histo">Histologie</button><button role="tab" aria-selected="false" aria-controls="c85-s-physio" data-s="c85-s-physio">Physiologie</button>',1)
figure3=f'''<figure id="c85-figure-originale-mediastin"><img src="assets/img/c85/alpha/codex/juanpere-2013-figure25-original.jpg" alt="Deux coupes tomodensitométriques originales : masse médiastinale antérieure repérée par les flèches en A et épanchement péricardique par la flèche ouverte en B." loading="lazy" width="609" height="219"><figcaption>Figure 3 — Lymphome médiastinal primitif chez un homme de19ans. <b>A :</b> les flèches blanches délimitent la masse antérieure ; l’astérisque indique ses remaniements kystiques. <b>B :</b> la flèche ouverte indique l’épanchement péricardique. Les repères sont ceux de la publication originale ; les annotations explicatives françaises sont ajoutées dans cette légende. Juanpere et al.,2013,figure25, {cite(RADIO,'article source')} ; {cite('https://creativecommons.org/licenses/by/4.0/','CC BY4.0')}. Les pixels de l’original sont conservés.</figcaption></figure>'''
figure4=f'''<figure id="c85-figure-originale-histologie"><img src="assets/img/c85/alpha/codex/histologie-2019-figure2-original.jpg" alt="Planche histologique originale du lymphome médiastinal : fibrose et agrégats tumoraux en A et B, puis marquages immunohistochimiques en C à F." loading="lazy" width="1181" height="1153"><figcaption>Figure 4 — Histologie authentique du lymphome médiastinal primitif. <b>A :</b> fibrose réticulaire. <b>B :</b> agrégats tumoraux séparés par une fibrose compartimentante. <b>C :</b> marquagep63. <b>D :</b> marquagebcl-6. <b>E :</b> marquageCD23. <b>F :</b> positivité focale pour la cyclineE dans l’exemple présenté. Ces annotations suivent les panneaux de la légende originale. Kim et al.,2019,figure2, {cite(HIST,'article source')} ; {cite('https://creativecommons.org/licenses/by/4.0/','CC BY4.0')}. L’ensemble morphologique et immunologique s’interprète avec les données cliniques ; cette planche ne permet pas à elle seule de diagnostiquer un patient.</figcaption></figure>'''
for n,fig in [(3,figure3),(4,figure4)]:
 text,count=re.subn(r'<figure><svg\b(?:(?!</figure>).)*?<figcaption>Figure '+str(n)+r'\b.*?</figcaption></figure>',fig,text,count=1,flags=re.S)
 if count!=1 and f'Figure {n} —' not in text:raise ValueError('Figure not found')
p.write_text(text)
p=ROOT/'chapters/C85/C85_a.html';t=p.read_text().replace('<section class="ilot" id="c85-5">','<section class="ilot" id="c85-5"><div data-semiology-clinical="C85"></div>',1);p.write_text(t)
p=ROOT/'chapters/C85/C85_b.html';t=p.read_text();anchor='<section class="ilot" id="c85-10">'
# Explicitly attributed update of PMBCL recommendations; the DLBCL-NOS section is distinct.
if 'c85-eha2025-update' not in t:
 match=re.search(re.escape(anchor)+r'(<h2>.*?</h2>)',t,re.S)
 if not match:raise ValueError('Treatment anchor missing')
 update=f'''<div class="key" id="c85-eha2025-update"><b>Actualisation européenne2025.</b> Pour le lymphome médiastinal primitif, les recommandations de l’Association européenne d’hématologie privilégient R-CHOP14 ou un schéma intensifié tel que DA-EPOCH-R et recommandent d’éviter R-CHOP21. En réponse métabolique complète, la radiothérapie médiastinale peut être omise. Un score Deauville4 en fin de traitement conduit à discuter une biopsie et une surveillance métabolique selon le contexte. Ces propositions concernent l’entité médiastinale ; elles ne se confondent pas avec les adaptations du lymphome diffus à grandes cellules B présentées dans la section suivante. {cite(EHA,'Recommandations EHA2025, sous-section Primary mediastinal B-cell lymphoma')}, consultées le2novembre2026. La prescription suisse exige ensuite les informations professionnelles des produits et la décision de l’équipe spécialisée.</div>'''
 t=t[:match.end()]+update+t[match.end():]
p.write_text(t)
for name in ['image-provenance.json','histology-provenance.json']:
 p=OUT/name;v=json.loads(p.read_text());v['visual_review']='Codex,02.11.2026 : original affiché, panneaux et repères comparés à légende; revue IA, pas validation humaine'
 if name.startswith('histology'):
  x=etree.fromstring(Path('/workspace/medina-source-cache/C85/histology2019.raw').read_bytes());v['author']='; '.join(' '.join(n.itertext()) for n in x.xpath('//contrib-group[@content-type="author"]//name'))
 p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
print('C85: sémiologie9sections +physiologie;6onglets sciences;2originaux annotés en légende;actualisationEHA2025')
